from fastapi import APIRouter, Request, Response
from psycopg import Error as DatabaseError
from psycopg_pool import PoolTimeout

router = APIRouter()


@router.get("/healthz")
async def healthz(response: Response) -> dict[str, str]:
    """Liveness: the worker is up and its event loop answers. Nothing else."""
    response.headers["Cache-Control"] = "no-store"
    return {"status": "ok"}


@router.get("/readyz")
async def readyz(request: Request, response: Response) -> dict[str, object]:
    """Readiness: send this instance traffic. False without PostgreSQL."""
    response.headers["Cache-Control"] = "no-store"
    try:
        async with request.app.state.pool.connection(timeout=1.0) as conn:
            await conn.execute("SELECT 1")
    except (DatabaseError, PoolTimeout):
        response.status_code = 503
        return {"status": "unavailable", "failing": ["postgres"]}
    return {"status": "ready"}

