import json
from typing import Annotated

from fastapi import APIRouter, Header, Request, Response

from app.config import get_settings
from app.problems import problem
from app.webhooks.signature import verify

router = APIRouter(prefix="/hooks", tags=["webhooks"])


@router.post("/email", status_code=204)
async def email_events(
    request: Request,
    signature: Annotated[str, Header(alias="Roombook-Signature")] = "",
) -> Response:
    raw = await request.body()  # the exact bytes the signature covers
    if not verify(get_settings().email_webhook_secret, signature, raw):
        return problem(request, 401, "bad-signature", "The Roombook-Signature header doesn't match the body.")
    event = json.loads(raw)

    async with request.app.state.pool.connection() as conn, conn.transaction():
        cur = await conn.execute(
            "INSERT INTO processed_events (event_id) VALUES (%s) ON CONFLICT DO NOTHING", (event["id"],)
        )
        if cur.rowcount == 1 and event["type"] == "email.bounced":
            await conn.execute(
                "UPDATE users SET email_bounced_at = now() WHERE lower(email) = lower(%s)", (event["data"]["to"],)
            )
    return Response(status_code=204)
